        for (const name of Object.keys(proxy.attributes)) proxy.deleteAttribute(name);
        proxy.setIndex(null);
        proxy.dispose();
      }
      reflectionProxies.clear();
      for (const frame of reflectionFrames) { frame.active = false; frame.used = 0; frame.swapped.length = 0; }
