/** Uniform source rocks use the same terrain-facet checks, without altering roots or tree policy. */
export function groundedNaturalGeometryY(terrain: Pick<Terrain, 'heightAt'>, placement: Pick<FloraTree, 'x' | 'z' | 's' | 'yaw'>,
