      b.meshes.push(entry);
      b.visibility.push({ wood: wood ? attachInstanceDistanceVisibility(wood) : null, leaf: leaf ? attachInstanceDistanceVisibility(leaf) : null });
      const installed: { wood: InstalledFoliage | null; leaf: InstalledFoliage | null } = { wood: null, leaf: null };
      if (foliage) {
        if (wood) installed.wood = installFoliage(wood.material as THREE.Material, { field: foliage, response, leaf: false, crown, hierarchical: foliageGeometryFeatures(lod.wood).hierarchical });
        if (leaf) installed.leaf = installFoliage(leaf.material as THREE.Material, { field: foliage, response, leaf: true, crown, look: (leaf.material as THREE.Material).userData.foliageLook as Partial<FoliageLook> | undefined, ...foliageGeometryFeatures(lod.leaf) });
      }
      const caster = (mesh: THREE.InstancedMesh | null, part: 'wood' | 'leaf') => {
        if (!mesh || !castsShadows) return null;
        const geometry = shadowGeometry(mesh.geometry);
        // Three casts an alpha-to-coverage material's shadow at a fixed 0.5 cut-off; a copy without it casts at the
        // leaves' own (A69). The copy is never drawn in colour: the casters show only for the sun's shadow pass.
        const material = (mesh.material as THREE.Material).clone();
        material.alphaToCoverage = false;
        casterMaterials.push(material);
        const c = new THREE.InstancedMesh(geometry, material, b.trees.length);
        // Like the colour batches, local pose is fixed; placements live in instanceMatrix and wind in the shader.
        c.matrixAutoUpdate = false;
        c.count = 0;
        c.visible = false;
        // Repaired foliage may have moved since the source sphere was cached.
        geometry.computeBoundingSphere();
        c.boundingSphere = new THREE.Sphere().makeEmpty();
        casterVisible.set(c, false);
        c.frustumCulled = false; // Visibility is cached against a guarded sun volume during refresh.
        c.castShadow = true;
        c.receiveShadow = false;
        c.name = `${mesh.name}:shadow`;
        const depth = shadowDepthMaterial(mesh.material as THREE.Material);
        if (foliage) installFoliageShadow(depth, { field: foliage, response, leaf: part === 'leaf', hierarchical: foliageGeometryFeatures(mesh.geometry).hierarchical }, installed[part] ?? undefined);
        casterCoverage.set(c, attachCasterCoverage(c, depth));
        c.customDepthMaterial = depth;
        shadowCasters.add(c);
        casterMaterials.push(depth);
        casterGeometries.push(geometry);
        return c;
      };
      b.casters.push({ wood: caster(wood, 'wood'), leaf: caster(leaf, 'leaf'),
        woodVisibility: new Uint8Array(b.trees.length), leafVisibility: new Uint8Array(b.trees.length), woodPrevious: 0, leafPrevious: 0 });
      // After the casters, which copy the colour material as it was.
