  }

  // Detached leaves drift downwind; leaves knocked loose by a strike join them.
  const windDirection = ctx.foliage?.wind.direction;
  const fallingLeaves = buildFallingLeaves(terrain, quality, trees, variantFor, windDirection ? Math.atan2(windDirection[1], windDirection[0]) : 0);
  group.add(fallingLeaves.group);
  const burst = ctx.foliage ? createLeafBurst(terrain, ctx.foliage.wind, undefined, reducedMotion) : null;
  if (burst) group.add(burst.mesh);

  /* ---- Per-frame selection ---- */
  const frustum = new THREE.Frustum();
  const pv = new THREE.Matrix4();
  const strikePoint = new THREE.Vector3();
  const strikeBounds = new THREE.Box3();
  const quat = new THREE.Quaternion();
  const scl = new THREE.Vector3();
  const pos = new THREE.Vector3();
  const up = new THREE.Vector3(0, 1, 0);
  // Tree placements are immutable for this module's lifetime. Wind bends vertices in the shader.
  for (const b of batches) {
    // Read the repaired source bounds: a tall tree's circumsphere contains large empty side regions.
    const localBox = new THREE.Box3();
    for (const lod of b.variant.lods) for (const geometry of [lod.wood, lod.leaf]) {
      if (!geometry) continue;
      if (!geometry.boundingBox) geometry.computeBoundingBox();
      localBox.union(geometry.boundingBox!);
    }
    // Include all leaf LODs: planar captures can temporarily substitute the middle source.
    // Shrink around the packed sphere's existing centre. Each instance can lose at least
    // this much radius, so their union retains the same two-metre wind guard without
    // admitting any draw rejected by the original bound or adding a per-instance walk.
    b.leafShrink = leafBoundsShrink(b.variant.lods, b.bounds) * Math.min(...b.trees.map(t => t.s));
    b.placements = b.trees.map(t => {
      const matrix = new THREE.Matrix4().compose(pos.set(t.x, t.y, t.z), quat.setFromAxisAngle(up, t.yaw), scl.set(t.s, t.s, t.s));
      const bounds = b.bounds.clone().applyMatrix4(matrix);
      bounds.radius += 2; // The same view/shadow edge guard used by every refresh.
      const box = localBox.clone().applyMatrix4(matrix).expandByScalar(2);
      return { matrix, bounds, box };
    });
    for (const caster of b.casters) for (const mesh of [caster.wood, caster.leaf]) {
      if (mesh) {
        casterBounds.set(mesh, casterPlacementBounds(mesh.geometry.boundingSphere!, b.placements));
      }
    }
  }
  const col = new THREE.Color();
  const shadowPlaneNormalDelta = new THREE.Vector3();
  const lastCam = new THREE.Vector3(1e9, 0, 0);
  const lastRotation = new THREE.Quaternion();
  const lastProjection = new THREE.Matrix4();
  const lastShadowFrustum = new THREE.Frustum();
  let lastShadowPresent = false;
  let lastViewOnly = false;
  let sinceRefresh = 1;
  let visible = 0;
  let drawTris = 0;
  let shadowTrees = 0;
  let shadowTris = 0;
  let disposed = false;
  const reflectionProxies = new Map<THREE.InstancedMesh, THREE.BufferGeometry>();
  const reflectionFrames: ReflectionSwapFrame[] = [];
  // High draws the full model at every distance (0.0.10, A62); its players may opt into Medium's bands (A76).
  let lodQuality = quality;

  const uploadPrefix = (attribute: THREE.BufferAttribute, count: number) => {
    attribute.clearUpdateRanges();
    attribute.addUpdateRange(0, Math.max(1, count) * attribute.itemSize);
    attribute.needsUpdate = true;
  };

  const packedTrees = new WeakMap<THREE.InstancedMesh, number[]>();
  const staticChanged = new Set<THREE.InstancedMesh>();
  const staticRanges = new WeakMap<THREE.InstancedMesh, { first: number; last: number }>();
  const uploadStatic = (mesh: THREE.InstancedMesh, attribute: THREE.BufferAttribute) => {
    const dirty = staticRanges.get(mesh)!;
    let first = dirty.first * attribute.itemSize, end = (dirty.last + 1) * attribute.itemSize;
    // A culled batch may have pending writes from earlier refreshes. Keep them until Three consumes the upload.
    for (const range of attribute.updateRanges) {
      first = Math.min(first, range.start); end = Math.max(end, range.start + range.count);
    }
    attribute.clearUpdateRanges();
    attribute.addUpdateRange(first, end - first);
    attribute.needsUpdate = true;
  };
  const coverageChanged = new Set<THREE.InstancedBufferAttribute>();
  const packStatic = (mesh: THREE.InstancedMesh | null, slot: number, tree: number, matrix: THREE.Matrix4, tint?: THREE.Color) => {
    if (!mesh) return;
    let packed = packedTrees.get(mesh);
    if (!packed) { packed = []; packedTrees.set(mesh, packed); }
    if (packed[slot] !== tree) {
      mesh.setMatrixAt(slot, matrix);
      if (tint) mesh.setColorAt(slot, tint);
      let dirty = staticRanges.get(mesh);
      if (!dirty) { dirty = { first: slot, last: slot }; staticRanges.set(mesh, dirty); }
      if (!staticChanged.has(mesh)) { dirty.first = slot; dirty.last = slot; }
      else { dirty.first = Math.min(dirty.first, slot); dirty.last = Math.max(dirty.last, slot); }
      staticChanged.add(mesh);
    }
    packed[slot] = tree;
  };

  // Toward the light, from the shadow camera's own near plane (it looks from the light into the scene).
  const toLight = new THREE.Vector3();
  const shadowEnd = new THREE.Vector3();
  /**
   * Air budget: a caster outside the view whose shadow cannot reach it either. Its shadow lies along the light's
   * direction away from it; sweep its bounds that way (as far as any receiver the shadow map holds) and if the whole
   * sweep lies beyond the view's left or right side, nothing on screen can be shaded by it. Only the sides are tested:
   * the water's reflection sees above and below the frame, never round to either side.
   */
  const shadowOutOfView = (sphere: THREE.Sphere): boolean => {
    if (toLight.y < 0.05) return false;
    shadowEnd.copy(sphere.center).addScaledVector(toLight, -SHADOW_REACH);
    for (let p = 0; p < 2; p++) {
      const plane = frustum.planes[p]!;
      if (plane.distanceToPoint(sphere.center) < -sphere.radius && plane.distanceToPoint(shadowEnd) < -sphere.radius) return true;
    }
    return false;
  };

  // Each tree's weights are consumed before the next tree; no result escapes this module's refresh.
  const shadowWeights: [number, number, number] = [0, 0, 0];
  // Reuse the fixed part order across every visible tree and LOD refresh.
  const colourParts = ['wood', 'leaf'] as const;

  const refresh = (cam: THREE.Camera, shadowFrustum: THREE.Frustum | null | undefined, viewOnly: boolean, casterGuardExceeded = false) => {
    const casterViewChanged = !!shadowFrustum && (!casterFrustumValid || casterGuardExceeded);
    if (casterViewChanged) {
      casterFrustum.copy(shadowFrustum!); casterFrustumValid = true;
      for (const batch of batches) for (const caster of batch.casters) { caster.woodVisibility.fill(0); caster.leafVisibility.fill(0); }
    }
    if (shadowFrustum) toLight.copy(shadowFrustum.planes[5]!.normal).negate().normalize();
    const cullShadows = viewOnly && !!shadowFrustum && forceLod < 0;
    staticChanged.clear();
    coverageChanged.clear();
    pv.multiplyMatrices(cam.projectionMatrix, cam.matrixWorldInverse);
    frustum.setFromProjectionMatrix(pv);
    const cx = cam.position.x;
    const cz = cam.position.z;
    visible = 0;
    drawTris = 0;
    shadowTrees = 0;
    shadowTris = 0;
    const counts = [0, 0, 0];
    for (const b of batches) {
      counts.fill(0);
      for (const caster of b.casters) {
        caster.woodPrevious = caster.wood?.count ?? 0; caster.leafPrevious = caster.leaf?.count ?? 0;
        if (caster.wood) caster.wood.count = 0;
        if (caster.leaf) caster.leaf.count = 0;
      }
      const v = b.variant;
      const pineShadows = usesPine(v.species);
      for (let treeIndex = 0; treeIndex < b.trees.length; treeIndex++) {
        const t = b.trees[treeIndex]!;
        const dx = t.x - cx;
        const dz = t.z - cz;
        const d = Math.hypot(dx, dz);
        const horizon = smoothDistanceFade(d, FLORA_FADE_START, FLORA_MAX_DISTANCE);
        if (horizon <= 0) continue;
        const { matrix: mtx, bounds: sphere, box } = b.placements[treeIndex]!;
        // Source-derived bounds include leaned crowns, all LOD cards and buried roots. A two-metre
        // guard preloads edge silhouettes. Retain off-screen casters only inside the actual
        // sun-shadow volume instead of paying for every tree in a large circle behind the player.
        const inView = frustum.intersectsSphere(sphere) && frustum.intersectsBox(box);
        const inShadow = b.casters.length > 0 && !!shadowFrustum?.intersectsSphere(sphere) && shadowFrustum.intersectsBox(box) && (inView || !cullShadows || !shadowOutOfView(sphere));
        if (!inView && !inShadow) continue;
        if (inShadow) {
          const sw: readonly number[] = forceLod >= 0 ? [0, 1, 2].map((l) => l === Math.min(2, Math.floor(forceLod)) ? 1 : 0) : floraShadowWeights(d, pineShadows, shadowWeights);
          let from = 0, cast = false;
          for (let sl = 0; sl < 3; sl++) {
            const to = from + sw[sl]!;
            const c = b.casters[sl];
            if (to > from + 1e-4 && c && (c.wood || c.leaf)) {
              for (const part of colourParts) {
                const mesh = c[part];
                if (!mesh) continue;
                const visibility = part === 'wood' ? c.woodVisibility : c.leafVisibility;
                // The guarded sun volume is unchanged on ordinary camera turns; cache each immutable placement.
                if (!visibility[treeIndex]) visibility[treeIndex] = shadowPlacementVisible(casterFrustum, casterBounds.get(mesh)!, treeIndex) ? 1 : 2;
                if (visibility[treeIndex] === 2) continue;
                // A crown reaching the sun volume must not keep its off-volume trunk in the instance prefix.
                const i = mesh.count++;
                packStatic(mesh, i, treeIndex, mtx);
                cast = true;
                const cov = casterCoverage.get(mesh);
                if (!cov) continue;
